import asyncio
import hmac
import importlib.util
import json
import os
from contextlib import asynccontextmanager

import httpx
from fastapi import FastAPI, WebSocket
from fastapi.middleware.cors import CORSMiddleware
from starlette.websockets import WebSocketDisconnect

from pipeline import local_ollama_url, run_pipeline
from session import register, cancel, cleanup_done
from state import get_state, set_state, remove_state
from vad import UtteranceCollector
from stt import _load_model as load_stt
from tts import _load_piper as load_tts, _model_path as tts_model_path

# Token is generated by the Tauri sidecar launcher (voice_sidecar.rs) and
# passed via VOICE_OS_TOKEN. If the variable is absent the endpoint is
# effectively unprotected, so we fail closed: a missing/empty token means
# every WebSocket connection is rejected.
_VOICE_TOKEN: str | None = os.environ.get("VOICE_OS_TOKEN") or None


@asynccontextmanager
async def lifespan(app: FastAPI):
    # Preload models at startup so first request isn't slow
    load_stt()
    load_tts()
    yield
    cleanup_done()


app = FastAPI(lifespan=lifespan)

app.add_middleware(
    CORSMiddleware,
    # Voice OS does not use browser cookies or HTTP authentication. WebSocket
    # authorization is handled separately, so wildcard origins are safe only
    # with credentials disabled.
    allow_origins=["*"],
    allow_credentials=False,
    allow_methods=["*"],
    allow_headers=["*"],
)


@app.get("/health")
async def health():
    # The production sidecar stores Piper under VOICE_PIPER_MODEL_DIR (the
    # Runtime Hub directory), not next to this bundled backend. Report the
    # actual model location so desktop health reflects a usable local TTS.
    tts_ok = False
    try:
        tts_ok = tts_model_path().exists()
    except OSError:
        tts_ok = False  # model file may not exist on first boot
    ollama_reachable = False
    try:
        async with httpx.AsyncClient(timeout=2.0) as client:
            response = await client.get(local_ollama_url().removesuffix("/api/chat") + "/api/tags")
            ollama_reachable = response.is_success
    except httpx.RequestError:
        ollama_reachable = False  # Ollama not reachable
    return {
        "status": "ok",
        "stt": importlib.util.find_spec("faster_whisper") is not None,
        "tts": tts_ok and importlib.util.find_spec("piper") is not None,
        "ollama": {"url": local_ollama_url(), "reachable": ollama_reachable},
    }


async def _process_pcm(
    ws: WebSocket,
    session_id: str,
    pcm: bytes,
    conversation_history: list[dict],
    config: dict | None = None,
) -> None:
    """Run the STT→LLM→TTS pipeline for one utterance and stream events back."""
    config = config or {}
    async for event in run_pipeline(session_id, pcm, conversation_history, model=config.get("model")):
        etype = event.get("type")
        try:
            if etype == "tts":
                await ws.send_bytes(event["audio"])
            else:
                await ws.send_json(event)
        except (WebSocketDisconnect, RuntimeError):
            return

        if etype == "state":
            set_state(session_id, event["value"])

        if etype == "stt":
            conversation_history.append({"role": "user", "content": event["text"]})

        if etype == "llm" and event.get("done"):
            reply = event.get("full_reply", "")
            if reply:
                conversation_history.append({"role": "assistant", "content": reply})
            if len(conversation_history) > 20:
                conversation_history[:] = conversation_history[-20:]


def _validate_token(provided: str | None) -> bool:
    """Return True only when provided matches the expected token (constant-time compare)."""
    if _VOICE_TOKEN is None or provided is None:
        return False
    return hmac.compare_digest(provided, _VOICE_TOKEN)


async def _handle_bytes_msg(
    ws: WebSocket,
    session_id: str,
    raw: bytes,
    collector: UtteranceCollector,
    conversation_history: list[dict],
    config: dict | None = None,
) -> None:
    """Handle an inbound PCM chunk.

    Audio is collected into whole utterances (speech, then a pause). Only a
    finished utterance starts an answer. QA 2026-10-22: every 1.5 s piece used
    to start its own answer and cancel the previous one, silent pieces included,
    so a question was cut up and its answer cancelled by the silence after it.
    """
    utterances = collector.feed(raw)
    # Barge-in: the user starts talking while Voice OS is speaking.
    if collector.in_utterance and get_state(session_id) == "speaking":
        cancel(session_id)
        set_state(session_id, "idle")
    for utterance in utterances:
        task = asyncio.create_task(_process_pcm(ws, session_id, utterance, conversation_history, config))
        register(session_id, task)


async def _handle_text_msg(
    ws: WebSocket,
    session_id: str,
    text: str,
    collector: UtteranceCollector,
    conversation_history: list[dict],
    config: dict | None = None,
) -> None:
    """Handle a JSON control message (reset, or the app's config)."""
    try:
        ctrl = json.loads(text)
    except json.JSONDecodeError:
        ctrl = {}  # ignore malformed control messages
    if ctrl.get("type") == "config" and config is not None:
        # The user's model choice in Alphonso (QA 2026-10-22: it used to be
        # fixed). The Ollama address is set only by the launcher
        # (LOCAL_OLLAMA_URL), never by a client, so it is not accepted here.
        model = str(ctrl.get("ollamaModel") or "").strip()
        if model:
            config["model"] = model[:200]
        await ws.send_json({"type": "config", "model": config.get("model"), "ollamaUrl": local_ollama_url()})
        return
    if ctrl.get("type") == "reset":
        cancel(session_id)
        conversation_history.clear()
        collector.reset()
        set_state(session_id, "idle")
        await ws.send_json({"type": "state", "value": "idle"})


@app.websocket("/ws")
async def ws_endpoint(ws: WebSocket):
    # Accept the WebSocket handshake first — close codes (1008) can only be
    # sent after the HTTP→WS upgrade completes. Token validation follows
    # immediately; unauthenticated connections are closed before any data flows.
    await ws.accept()
    if not _validate_token(ws.query_params.get("token")):
        await ws.close(code=1008)  # 1008 = Policy Violation
        return

    session_id = ws.headers.get("x-session", "anon")
    set_state(session_id, "idle")
    collector = UtteranceCollector()
    config: dict = {}
    conversation_history: list[dict] = []

    try:
        while True:
            msg = await ws.receive()
            # A "websocket.disconnect" message signals the client has closed the
            # connection. Break immediately; calling receive() again after this
            # raises RuntimeError in Starlette.
            if msg.get("type") == "websocket.disconnect":
                break
            if "bytes" in msg:
                await _handle_bytes_msg(ws, session_id, msg["bytes"], collector, conversation_history, config)
            elif "text" in msg:
                await _handle_text_msg(ws, session_id, msg["text"], collector, conversation_history, config)
    finally:
        cancel(session_id)
        remove_state(session_id)
        cleanup_done()
